import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Navigation tree","description":"","frontmatter":{"title":"Navigation tree","covers":{"screens":["SCR-055"],"stories":["US-054","US-094","US-095","US-096","US-097"]}},"headers":[],"relativePath":"usage/navigation.md","filePath":"usage/navigation.md"}`),a={name:`usage/navigation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="navigation-tree" tabindex="-1">Navigation tree <a class="header-anchor" href="#navigation-tree" aria-label="Permalink to “Navigation tree”">​</a></h1><p>The navigation tree arranges catalogs, entities and solutions in folders, for example <em>IT Landscape &gt; Application Inventory</em>, so that you find what you need for your task without searching. Everybody with the permission <code>entity:read</code> (for example the role <code>viewer</code>) sees the tree. Changing it needs the permissions <code>viewpoint:manage</code> and <code>entity:read</code> (role <code>enterprise-architect</code>).</p><h2 id="the-sidebar" tabindex="-1">The sidebar <a class="header-anchor" href="#the-sidebar" aria-label="Permalink to “The sidebar”">​</a></h2><p>After login, the sidebar on the left of every page shows the tree. It starts at the folder <em>Repository</em>.</p><ul><li><strong>Open and close a folder:</strong> choose the arrow or the name of the folder. The sidebar remembers which folders are open until you close the browser tab.</li><li><strong>Open an entry:</strong> choose it. A catalog opens with its default view, if it has one (see <a href="./catalogs#views">Views</a>); an entity opens its page, a solution its solution page.</li><li><strong>Narrow screens:</strong> the sidebar is hidden; the menu button at the left of the header opens it. Choosing an entry closes it again.</li></ul><p>Folders and entries keep the order in which you arrange them (see <a href="#reorganize-the-tree">Reorganize the tree</a>); new folders and entries go to the end. An entry shows its display label if it has one, otherwise the name of the catalog, entity or solution. An icon shows the kind of entry, and a person icon marks a personal catalog.</p><h2 id="folders" tabindex="-1">Folders <a class="header-anchor" href="#folders" aria-label="Permalink to “Folders”">​</a></h2><p>With the permissions to change the tree, the button <em>…</em> next to a folder offers:</p><ul><li><strong>New folder:</strong> creates a folder inside it. Enter a name and choose <em>Create</em>.</li><li><strong>Rename:</strong> changes the name of the folder, the folder <em>Repository</em> included. Its entries and subfolders stay.</li><li><strong>Move up</strong>, <strong>Move down</strong> and <strong>Move to…:</strong> see <a href="#reorganize-the-tree">Reorganize the tree</a>.</li><li><strong>Delete:</strong> asks first and names how many subfolders and entries the deletion removes. The folder is deleted with all its subfolders and entries. <strong>No catalog, entity or solution is deleted</strong>; they stay available and in other folders. The folder <em>Repository</em> cannot be deleted.</li></ul><p>A folder name has 1 to 255 characters and is unique within its folder, regardless of upper and lower case; otherwise the dialog says <em>A folder with this name already exists</em>. The tree has at most 10 levels below <em>Repository</em> and at most 500 folders.</p><h2 id="place-a-catalog-an-entity-or-a-solution" tabindex="-1">Place a catalog, an entity or a solution <a class="header-anchor" href="#place-a-catalog-an-entity-or-a-solution" aria-label="Permalink to “Place a catalog, an entity or a solution”">​</a></h2><ol><li>Choose <em>Place in navigation</em>: <ul><li>for a catalog, on the page of the catalog;</li><li>for an entity, in its row of a catalog (not offered in catalogs of connections);</li><li>for a solution, in the header of the solution page.</li></ul></li><li>Under <em>Folder</em>, choose the folder by its path, for example <em>Repository / IT Landscape</em>.</li><li>Optionally, enter a <em>Display label</em>. The tree then shows it instead of the name, for example <em>System Inventory</em> for <em>Application Inventory</em>. The catalog, entity or solution keeps its name.</li><li>Choose <em>Place</em>.</li></ol><p>Each of them can be placed in several folders, but only once per folder. A folder has at most 200 entries. If the folder already holds it or is full, the dialog says so, for example <em>The catalog is already in this folder, or the folder is full</em>.</p><h2 id="reorganize-the-tree" tabindex="-1">Reorganize the tree <a class="header-anchor" href="#reorganize-the-tree" aria-label="Permalink to “Reorganize the tree”">​</a></h2><p>With the permissions to change the tree, you arrange folders and entries in the sidebar:</p><ul><li><strong>Drag and drop:</strong> drag a folder or an entry to another place in the same folder or into another folder. Where it cannot go, the sidebar shows <em>Cannot be dropped here</em>, for example a folder dropped into its own subfolder.</li><li><strong>Without a mouse:</strong> the button <em>…</em> next to a folder or an entry offers <em>Move up</em>, <em>Move down</em> and <em>Move to…</em>. <em>Move to…</em> asks for the target folder and moves it to the end there.</li></ul><p>A move keeps the rules of the tree: at most 10 levels, at most 200 entries per folder, unique folder names, and an entry only once per folder. Reordering within a full folder is possible. Otherwise the sidebar says <em>It cannot be moved there. The tree may have changed meanwhile.</em> If a folder or entry no longer exists because someone else changed the tree meanwhile, the sidebar reads the current tree again.</p><h2 id="remove-an-entry-from-the-tree" tabindex="-1">Remove an entry from the tree <a class="header-anchor" href="#remove-an-entry-from-the-tree" aria-label="Permalink to “Remove an entry from the tree”">​</a></h2><p>The button <em>×</em> next to an entry removes it from that folder. Only this entry is removed: the catalog, entity or solution itself and its entries in other folders stay.</p><h2 id="deleted-entities" tabindex="-1">Deleted entities <a class="header-anchor" href="#deleted-entities" aria-label="Permalink to “Deleted entities”">​</a></h2><p>When an entity is deleted, its entries stay in the tree and show the marker <em>Deleted</em>. Remove them with <em>×</em>, or restore the entity; the marker then disappears.</p><h2 id="personal-catalogs" tabindex="-1">Personal catalogs <a class="header-anchor" href="#personal-catalogs" aria-label="Permalink to “Personal catalogs”">​</a></h2><p>You can place your own personal catalog like a shared one. Only you see its entry: the tree never shows other people&#39;s personal catalogs, so it never leads to a catalog you cannot open. If you later share the catalog, everybody sees the entry.</p><p>Every change of the tree, moves included, is recorded in the audit trail.</p><h2 id="through-the-api" tabindex="-1">Through the API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to “Through the API”">​</a></h2><ul><li><code>GET /views/explorer</code> returns the tree from the root as you see it, in its manual order: each folder with <code>id</code>, <code>name</code>, <code>parentId</code>, <code>sortOrder</code>, <code>items</code> and <code>children</code>; each entry with <code>itemType</code> (<code>catalog</code>, <code>entity</code> or <code>solution</code>), <code>referenceId</code> (catalog or solution ID) or <code>entityId</code>, <code>displayLabel</code>, <code>name</code>, <code>scope</code> and <code>deleted</code>.</li><li><code>POST /tree-nodes</code> with <code>name</code> and <code>parentId</code> creates a folder; <code>PATCH /tree-nodes/{nodeId}</code> with <code>name</code> renames it; <code>DELETE /tree-nodes/{nodeId}</code> deletes it.</li><li><code>POST /tree-nodes/{nodeId}/items</code> with <code>itemType</code>, <code>referenceId</code> or <code>entityId</code> and an optional <code>displayLabel</code> places an entry; <code>DELETE /tree-nodes/{nodeId}/items/{itemId}</code> removes it.</li><li><code>PUT /tree-nodes/{nodeId}/position</code> with <code>parentId</code> and <code>position</code> moves a folder; <code>PUT /tree-nodes/{nodeId}/items/{itemId}/position</code> with <code>nodeId</code> and <code>position</code> moves an entry. The position counts the entries you see, from 0.</li></ul><p>Every change answers with the whole tree. Invalid input is rejected with 422 and names the field in <code>invalidFields</code>, for example <code>name</code> for a taken folder name, <code>parentId</code> for a move that would create a cycle or go too deep, or <code>nodeId</code> for a target folder that already holds the entry or is full.</p>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};